/** @param {{des: object}} api */
export default function hellfill({ des, selection, percent, shuffle, math, hell_tweaks, u, luaList, luaLen, type }) {
    //	The "fill" level for gehennom.
    //
    //	This level is used to fill out any levels not occupied by
    //	specific levels.
    //

    function hellobjects() {
        // luaList keeps Lua's 1-based indices, so objclass[n] means the same here.
        const objclass = luaList('(', '/', '=', '+', ')', '[', '?', '*', '%');
        shuffle(objclass);

        des.object(objclass[1]);
        des.object(objclass[1]);
        des.object(objclass[2]);
        des.object(objclass[3]);
        des.object(objclass[4]);
        des.object(objclass[5]);
        des.object();
        des.object();
    }

    //

    function hellmonsters() {
        // luaList keeps Lua's 1-based indices, so monclass[n] means the same here.
        const monclass = luaList('V', 'D', ' ', '&', 'Z');
        shuffle(monclass);

        des.monster({ 'class': monclass[1], peaceful: 0 });
        des.monster({ 'class': monclass[1], peaceful: 0 });
        des.monster({ 'class': monclass[2], peaceful: 0 });
        des.monster({ 'class': monclass[2], peaceful: 0 });
        des.monster({ 'class': monclass[3], peaceful: 0 });
        des.monster({ 'class': monclass[4], peaceful: 0 });
        des.monster({ peaceful: 0 });
        des.monster({ 'class': 'H', peaceful: 0 });
    }

    //

    function helltraps() {
        for (let i = 1; i <= 12; i++) {
            des.trap();
        }
    }

    //

    function populatemaze() {
        for (let i = 1, iEnd = math.random(8) + 11; i <= iEnd; i++) {
            if (percent(50)) {
                des.object('*');
            } else {
                des.object();
            }
        }

        for (let i = 1, iEnd = math.random(10) + 2; i <= iEnd; i++) {
            des.object('`');
        }

        for (let i = 1, iEnd = math.random(3); i <= iEnd; i++) {
            des.monster({ id: 'minotaur', peaceful: 0 });
        }

        for (let i = 1, iEnd = math.random(5) + 7; i <= iEnd; i++) {
            des.monster({ peaceful: 0 });
        }

        for (let i = 1, iEnd = math.random(6) + 7; i <= iEnd; i++) {
            des.gold();
        }

        for (let i = 1, iEnd = math.random(6) + 7; i <= iEnd; i++) {
            des.trap();
        }
    }

    //

    function rnd_halign() {
        // luaList keeps Lua's 1-based indices, so aligns[n] means the same here.
        const aligns = luaList('half-left', 'center', 'half-right');
        return aligns[math.random(1, luaLen(aligns))];
    }

    function rnd_valign() {
        const aligns = luaList('top', 'center', 'bottom');
        return aligns[math.random(1, luaLen(aligns))];
    }

    // the prefab maps must have contents-function, or populatemaze()
    // puts the stuff only inside the prefab map.
    // contains either a function, or an object with "repeatable" and "contents".
    // function alone implies not repeatable.
    // luaList keeps Lua's 1-based indices, so hell_prefabs[n] means the same here.
    const hell_prefabs = luaList(
        {
            repeatable: true,
            contents: () => {
                des.map({
                    halign: rnd_halign(), valign: 'center', map: `......
......
......
......
......
......
......
......
......
......
......
......
......
......
......
......`,
                    contents: () => {},
                });
            },
        },
        {
            repeatable: true,
            contents: () => {
                des.map({
                    halign: rnd_halign(), valign: 'center', map: `xxxxxx.....xxxxxx
xxxx.........xxxx
xx.............xx
xx.............xx
x...............x
x...............x
.................
.................
.................
.................
.................
x...............x
x...............x
xx.............xx
xx.............xx
xxxx.........xxxx
xxxxxx.....xxxxxx
`,
                    contents: () => {},
                });
            },
        },
        (coldhell) => {
            des.map({
                halign: rnd_halign(), valign: rnd_valign(), map: `xxxxxx.xxxxxx
xLLLLLLLLLLLx
xL---------Lx
xL|.......|Lx
xL|.......|Lx
.L|.......|L.
xL|.......|Lx
xL|.......|Lx
xL---------Lx
xLLLLLLLLLLLx
xxxxxx.xxxxxx
`,
                contents: () => {
                    des.non_diggable(selection.area(2, 2, 10, 8));
                    des.region(selection.area(4, 4, 8, 6), 'lit');
                    des.exclusion({ type: 'teleport', region: [2, 2, 10, 8] });
                    if (coldhell) {
                        des.replace_terrain({ region: [1, 1, 11, 9], fromterrain: 'L', toterrain: 'P' });
                    }
                    const dblocs = luaList(
                        { x: 1, y: 5, dir: 'east', state: 'closed' },
                        { x: 11, y: 5, dir: 'west', state: 'closed' },
                        { x: 6, y: 1, dir: 'south', state: 'closed' },
                        { x: 6, y: 9, dir: 'north', state: 'closed' },
                    );
                    shuffle(dblocs);
                    for (let i = 1, iEnd = math.random(1, luaLen(dblocs)); i <= iEnd; i++) {
                        des.drawbridge(dblocs[i]);
                    }
                    const mons = luaList('H', 'T', '@');
                    shuffle(mons);
                    for (let i = 1, iEnd = 3 + math.random(1, 5); i <= iEnd; i++) {
                        des.monster(mons[1], 6, 5);
                    }
                },
            });
        },
        {
            repeatable: true,
            contents: () => {
                des.map({
                    halign: 'center', valign: 'center', map: `..............................................................
..............................................................
..............................................................
..............................................................
..............................................................`,
                    contents: () => {},
                });
            },
        },
        {
            repeatable: true,
            contents: () => {
                des.map({
                    halign: rnd_halign(), valign: rnd_valign(), lit: true, map: `x.....x
.......
.......
.......
.......
.......
x.....x`,
                    contents: () => {},
                });
            },
        },
        () => {
            des.map({
                halign: rnd_halign(), valign: rnd_valign(), map: `BBBBBBB
B.....B
B.....B
B.....B
B.....B
B.....B
BBBBBBB`,
                contents: () => {
                    des.region({ region: [2, 2, 2, 2], type: 'temple', filled: 1, irregular: 1 });
                    des.altar({ x: 3, y: 3, align: 'noalign', type: percent(75) && 'altar' || 'shrine' });
                },
            });
        },
        () => {
            des.map({
                halign: rnd_halign(), valign: rnd_valign(), map: `..........
..........
..........
...FFFF...
...F..F...
...F..F...
...FFFF...
..........
..........
..........`,
                contents: () => {
                    des.exclusion({ type: 'teleport', region: [4, 4, 5, 5] });
                    const mons = luaList('Angel', 'D', 'H', 'L');
                    des.monster(mons[math.random(1, luaLen(mons))], 4, 4);
                },
            });
        },
        () => {
            des.map({
                halign: rnd_halign(), valign: rnd_valign(), map: `.........
.}}}}}}}.
.}}---}}.
.}--.--}.
.}|...|}.
.}--.--}.
.}}---}}.
.}}}}}}}.
.........
`,
                contents: (rm) => {
                    des.exclusion({ type: 'teleport', region: [3, 3, 5, 5] });
                    des.monster('L', 4, 4);
                },
            });
        },
        () => {
            const mapstr = percent(30) && `.....
.LLL.
.LZL.
.LLL.
.....` || `.....
.PPP.
.PWP.
.PPP.
.....`;
            for (let dx = 1; dx <= 5; dx++) {
                des.map({
                    x: dx * 14 - 4, y: math.random(3, 15),
                    map: mapstr, contents: () => {},
                });
            }
        },
        {
            repeatable: true,
            contents: () => {
                const mapstr = `...
...
...
...
...
...
...
...
...
...
...
...
...
...
...
...
...`;
                for (let dx = 1; dx <= 3; dx++) {
                    des.map({
                        x: math.random(3, 75), y: 3,
                        map: mapstr, contents: () => {},
                    });
                }
            },
        },
    );

    function rnd_hell_prefab(coldhell) {
        let dorepeat = true;
        let nloops = 0;
        do {
            nloops = nloops + 1;
            const pf = math.random(1, luaLen(hell_prefabs));
            const fab = hell_prefabs[pf];
            const fabtype = type(fab);

            if (fabtype === 'function') {
                fab(coldhell);
                dorepeat = false;
            } else if (fabtype === 'table') {
                fab.contents(coldhell);
                dorepeat = !(fab.repeatable && math.random(0, nloops * 2) === 0);
            }
        } while (!((!dorepeat) || (nloops > 5)));
    }

    // luaList keeps Lua's 1-based indices, so hells[n] means the same here.
    const hells = luaList(
        // 1: "mines" style with lava
        () => {
            des.level_init({ style: 'solidfill', fg: ' ', lit: 0 });
            des.level_flags('mazelevel', 'noflip');
            des.level_init({ style: 'mines', fg: '.', smoothed: true, joined: true, lit: 0, walled: true });
            des.replace_terrain({ fromterrain: ' ', toterrain: 'L' });
            des.replace_terrain({ fromterrain: '.', toterrain: 'L', chance: 5 });
            des.replace_terrain({ mapfragment: `w`, toterrain: 'L', chance: 20 });
            des.replace_terrain({ mapfragment: `w`, toterrain: '.', chance: 15 });
        },
        // 2: mazes like original, with some hell_tweaks
        () => {
            des.level_init({ style: 'solidfill', fg: ' ', lit: 0 });
            des.level_flags('mazelevel', 'noflip');
            des.level_init({ style: 'mazegrid', bg: '-' });
            des.mazewalk({ coord: [1, 10], dir: 'east', stocked: false });
            const tmpbounds = selection.match('-');
            const bnds = selection.bounds(tmpbounds);
            const protected_area = selection.fillrect(bnds.lx, bnds.ly + 1, bnds.hx - 2, bnds.hy - 1);
            hell_tweaks(selection.negate(protected_area));
            if (percent(25)) {
                rnd_hell_prefab(false);
            }
        },
        // 3: mazes, style 1: wall thick = 1, random wid corr
        () => {
            des.level_init({ style: 'solidfill', fg: ' ', lit: 0 });
            des.level_flags('mazelevel', 'noflip');
            des.level_init({ style: 'maze', wallthick: 1 });
        },
        // 4: mazes, style 2: replace wall with iron bars or lava
        () => {
            const cwid = math.random(4);
            des.level_init({ style: 'solidfill', fg: ' ', lit: 0 });
            des.level_flags('mazelevel', 'noflip');
            des.level_init({ style: 'maze', wallthick: 1, corrwid: cwid });
            const outside_walls = selection.match(' ');
            const wallterrain = luaList('F', 'L');
            shuffle(wallterrain);
            des.replace_terrain({ mapfragment: 'w', toterrain: wallterrain[1] });
            if (cwid === 1) {
                if (wallterrain[1] === 'F' && percent(80)) {
                    // replace some horizontal iron bars walls with floor
                    des.replace_terrain(
                        { mapfragment: '.\nF\n.', toterrain: '.', chance: 25 * math.random(4) }
                    );
                } else if (percent(25)) {
                    rnd_hell_prefab(false);
                }
            }
            des.terrain(outside_walls, ' ');
            // return the outside back to solid wall
        },
        // 5: mazes, thick walls, occasionally lava instead of walls
        () => {
            const wwid = 1 + math.random(2);
            des.level_init({ style: 'solidfill', fg: ' ', lit: 0 });
            des.level_flags('mazelevel', 'noflip');
            des.level_init({ style: 'maze', wallthick: wwid, corrwid: math.random(2) });
            if (percent(50)) {
                const outside_walls = selection.match(' ');
                des.replace_terrain({ mapfragment: 'w', toterrain: 'L' });
                des.terrain(outside_walls, ' ');
                // return the outside back to solid wall
                if (wwid === 3 && percent(40)) {
                    const sel = selection.match('LLL\nLLL\nLLL');
                    des.terrain(selection.percentage(sel, 30 * math.random(4)), 'Z');
                }
            }
        },
        // 6: cold maze, with ice and water
        () => {
            const cwid = math.random(4);
            des.level_init({ style: 'solidfill', fg: ' ', lit: 0 });
            des.level_flags('mazelevel', 'noflip', 'cold');
            des.level_init({ style: 'maze', wallthick: 1, corrwid: cwid });
            const outside_walls = selection.match(' ');
            const icey = selection.filter_mapchar(
                selection.grow(selection.percentage(selection.negate(), 10)), '.'
            );
            des.terrain(icey, 'I');
            if (cwid > 1) {
                // turn some ice into wall of water
                des.terrain(selection.percentage(icey, 1), 'W');
            }
            des.terrain(selection.percentage(icey, 5), 'P');
            if (percent(25)) {
                des.terrain(selection.match('w'), 'W');
                // walls of water
            }
            if (cwid === 1 && percent(25)) {
                rnd_hell_prefab(true);
            }
            des.terrain(outside_walls, ' ');
            // return the outside back to solid wall
        },
        // 7: open cavern, "mines" with more space
        () => {
            // walls are either stone or lava
            const wter = percent(50) && ' ' || 'L';
            des.level_init({ style: 'solidfill', fg: ' ', lit: 0 });
            des.level_flags('mazelevel', 'noflip');
            des.level_init({ style: 'mines', fg: '.', bg: wter, smoothed: true, joined: true, lit: 0 });
            const sel = selection.grow(selection.match('.'));
            des.terrain({ selection: sel, typ: '.', lit: 0 });

            const border = selection.rect(0, 0, 78, 20);
            des.terrain({ selection: border, typ: wter, lit: 0 });
            des.wallify();
        },
    );

    const hellno = math.random(1, luaLen(hells));
    hells[hellno]();

    //

    des.stair('up');
    if (u.invocation_level) {
        des.trap('vibrating square');
    } else {
        des.stair('down');
    }

    populatemaze();
}
